-- Generated by tools/gen_floor_content.py. Every quest in SpireQuests.list (lib/spirebound/quests.lua and
-- floor_content.lua) gets a quest-log entry with one mission; the text comes from SpireQuests.logText.
local quests = {}
for i, q in ipairs(SpireQuests.list) do
	quests[i] = {
		name = q.name,
		startStorageId = q.storage,
		startStorageValue = 1,
		missions = {
			[1] = {
				name = q.name,
				storageId = q.storage,
				missionId = i,
				startValue = 1,
				endValue = 3,
				description = function(player)
					return SpireQuests.logText(q, SpireQuests.state(player, q), SpireQuests.progress(player, q))
				end,
			},
		},
	}
end
return quests
